<script setup lang="ts">
import { Check, ChevronDown, X, LoaderCircle, ImagePlus, Trash2 } from 'lucide-vue-next'
type CompanyBrandOption={id:number;name:string;logo_url?:string|null}
type CompanyOption={id?:number;name:string;logo:string;group:string;businessEntityId?:number}; type OperationalArea={id:number;name:string}
type ExistingPhoto={id:number;photoUrl:string}
const props=defineProps<{modelValue:boolean;groups:{id:number;name:string}[];companies:{id:number;name:string;groupId:number|null;businessEntityId?:number|null;brands:CompanyBrandOption[]}[];areas:OperationalArea[];loading?:boolean;editCompany?:{group?:string;company?:string;area?:string;nace?:string;dangerClass?:string;sgk?:string;brandId?:number|null;photos?:ExistingPhoto[]}|null}>()
const emit=defineEmits<{ 'update:modelValue':[value:boolean]; save:[payload:{group:string;company:string;companyId?:number;area:string;areaId?:number;nace:string;dangerClass:string;sgk:string;brandId?:number|null;photos:File[];removePhotoIds:number[]}] }>(); const selectedGroup=ref('');const selectedCompany=ref('');const selectedArea=ref('');const nace=ref('');const dangerClass=ref('');const sgk=ref('');const selectedBrandId=ref<number|null>(null); const existingPhotos=ref<ExistingPhoto[]>([]); const removedPhotoIds=ref<number[]>([]); const newPhotoFiles=ref<File[]>([]); const newPhotoPreviews=ref<string[]>([]); const fileInput=ref<HTMLInputElement|null>(null);
const filteredCompanies=computed(()=>{const group=props.groups.find(x=>x.name===selectedGroup.value);return group?props.companies.filter(x=>x.groupId===group.id):[]});const selectedCompanyOption=computed(()=>filteredCompanies.value.find(x=>x.name===selectedCompany.value));const selectedAreaOption=computed(()=>props.areas.find(x=>x.name===selectedArea.value));
const revokeNewPreviews=()=>{newPhotoPreviews.value.forEach(url=>URL.revokeObjectURL(url))};
const reset=()=>{selectedGroup.value='';selectedCompany.value='';selectedArea.value='';nace.value='';dangerClass.value='';sgk.value='';selectedBrandId.value=null;existingPhotos.value=[];removedPhotoIds.value=[];revokeNewPreviews();newPhotoFiles.value=[];newPhotoPreviews.value=[];if(fileInput.value)fileInput.value.value=''};
const companyBrands=computed(()=>selectedCompanyOption.value?.brands||[]);
const brandSelectionRequired=computed(()=>companyBrands.value.length>1);
const fillEdit=()=>{const edit=props.editCompany;if(!edit)return;selectedGroup.value=edit.group||'';existingPhotos.value=[...(edit.photos||[])];removedPhotoIds.value=[];revokeNewPreviews();newPhotoFiles.value=[];newPhotoPreviews.value=[];nextTick(()=>{selectedCompany.value=edit.company||'';selectedArea.value=edit.area||'';nace.value=edit.nace||'';dangerClass.value=edit.dangerClass||'';sgk.value=edit.sgk||'';nextTick(()=>{selectedBrandId.value=edit.brandId??null})})};
const onPhotoChange=(e:Event)=>{const files=Array.from((e.target as HTMLInputElement).files||[]);files.forEach(file=>{newPhotoFiles.value.push(file);newPhotoPreviews.value.push(URL.createObjectURL(file))});if(fileInput.value)fileInput.value.value=''};
const removeExistingPhoto=(id:number)=>{existingPhotos.value=existingPhotos.value.filter(p=>p.id!==id);removedPhotoIds.value.push(id)};
const removeNewPhoto=(index:number)=>{URL.revokeObjectURL(newPhotoPreviews.value[index]);newPhotoFiles.value.splice(index,1);newPhotoPreviews.value.splice(index,1)};
watch(()=>props.modelValue,(open)=>{if(!open){reset();return}reset();nextTick(fillEdit)},{flush:'post'});
watch(()=>props.editCompany,(edit)=>{if(!props.modelValue)return;reset();nextTick(()=>{if(edit)fillEdit()})},{deep:true,flush:'post'});
watch(selectedGroup,(value,old)=>{if(value!==old&&!props.editCompany)selectedCompany.value=''});
watch(companyBrands,(brands)=>{selectedBrandId.value=brands.length===1?brands[0].id:null});
const close=()=>emit('update:modelValue',false);const save=()=>{if(!selectedGroup.value||!selectedCompany.value||!dangerClass.value)return;if(brandSelectionRequired.value&&!selectedBrandId.value)return;emit('save',{group:selectedGroup.value,company:selectedCompany.value,companyId:selectedCompanyOption.value?.id,area:selectedArea.value,areaId:selectedAreaOption.value?.id,nace:nace.value,dangerClass:dangerClass.value,sgk:sgk.value,brandId:selectedBrandId.value,photos:[...newPhotoFiles.value],removePhotoIds:[...removedPhotoIds.value]})}
</script>
<template><div v-if="modelValue" class="fixed inset-0 z-[1000] flex items-center justify-center bg-gray-900/40 p-4 backdrop-blur-[2px]"><div class="w-full max-w-2xl overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-2xl dark:border-gray-800 dark:bg-gray-900"><div class="flex items-center justify-between border-b border-gray-200 px-5 py-4 dark:border-gray-800"><div><h2 class="text-base font-semibold text-gray-900 dark:text-white/90">{{editCompany ? 'Firma Düzenle' : 'Firma Ekle'}}</h2><p class="mt-0.5 text-xs text-gray-500 dark:text-gray-400">Firmayı bu lokasyon ve operasyonel alan ile ilişkilendirin.</p></div><button type="button" class="flex h-8 w-8 items-center justify-center rounded-lg text-gray-500 hover:bg-gray-100 dark:hover:bg-white/5" @click="close"><X :size="18"/></button></div><div v-if="loading" class="flex items-center justify-center gap-2 px-5 py-12 text-sm text-gray-500"><LoaderCircle :size="18" class="animate-spin"/> Veriler yükleniyor...</div><div v-else class="grid gap-4 p-5 sm:grid-cols-2"><label><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">Grup</span><div class="relative"><select v-model="selectedGroup" class="h-11 w-full appearance-none rounded-lg border border-gray-200 bg-white px-3 pr-9 text-sm text-gray-700 outline-none focus:border-brand-500 focus:ring-4 focus:ring-brand-500/10 dark:border-gray-700 dark:bg-gray-950 dark:text-white/90"><option value="">Grup seçiniz</option><option v-for="group in groups" :key="group.id" :value="group.name">{{group.name}}</option></select><ChevronDown :size="15" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"/></div></label><label><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">Firma</span><div class="relative"><select v-model="selectedCompany" :disabled="!selectedGroup" class="h-11 w-full appearance-none rounded-lg border border-gray-200 bg-white px-3 pr-9 text-sm text-gray-700 outline-none disabled:cursor-not-allowed disabled:bg-gray-50 focus:border-brand-500 focus:ring-4 focus:ring-brand-500/10 dark:border-gray-700 dark:bg-gray-950 dark:text-white/90"><option value="">Firma seçiniz</option><option v-for="item in filteredCompanies" :key="item.id" :value="item.name">{{item.name}}</option></select><ChevronDown :size="15" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"/></div></label><div v-if="brandSelectionRequired" class="sm:col-span-2"><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">Marka</span><div class="flex flex-wrap gap-2"><button v-for="brand in companyBrands" :key="brand.id" type="button" class="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm transition" :class="selectedBrandId===brand.id?'border-brand-500 bg-brand-50 text-brand-700 dark:bg-brand-500/10 dark:text-brand-300':'border-gray-200 text-gray-600 hover:bg-gray-50 dark:border-gray-700 dark:text-gray-300 dark:hover:bg-white/5'" @click="selectedBrandId=brand.id"><span class="flex h-6 w-6 items-center justify-center overflow-hidden rounded-full border border-gray-200 bg-white dark:border-gray-700"><img v-if="brand.logo_url" :src="brand.logo_url" :alt="brand.name" class="h-full w-full object-contain"/><span v-else class="text-[10px] font-semibold text-gray-500">{{brand.name.charAt(0)}}</span></span>{{brand.name}}</button></div></div><div class="sm:col-span-2"><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">Şube Fotoğrafları <span class="font-normal text-gray-400">(opsiyonel, birden fazla seçilebilir)</span></span><div class="flex flex-wrap items-center gap-3"><div v-for="photo in existingPhotos" :key="`existing-${photo.id}`" class="relative h-16 w-16 shrink-0 overflow-hidden rounded-lg border border-gray-200 dark:border-gray-700"><img :src="photo.photoUrl" alt="Şube fotoğrafı" class="h-full w-full object-cover"/><button type="button" class="absolute right-0.5 top-0.5 flex h-5 w-5 items-center justify-center rounded-full bg-gray-900/70 text-white hover:bg-error-600" title="Fotoğrafı Kaldır" @click="removeExistingPhoto(photo.id)"><Trash2 :size="11"/></button></div><div v-for="(preview,index) in newPhotoPreviews" :key="`new-${index}`" class="relative h-16 w-16 shrink-0 overflow-hidden rounded-lg border border-brand-200 dark:border-brand-500/40"><img :src="preview" alt="Yeni şube fotoğrafı" class="h-full w-full object-cover"/><button type="button" class="absolute right-0.5 top-0.5 flex h-5 w-5 items-center justify-center rounded-full bg-gray-900/70 text-white hover:bg-error-600" title="Fotoğrafı Kaldır" @click="removeNewPhoto(index)"><Trash2 :size="11"/></button></div><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" multiple class="hidden" @change="onPhotoChange"/><button type="button" class="flex h-16 w-16 shrink-0 flex-col items-center justify-center gap-1 rounded-lg border border-dashed border-gray-300 text-gray-400 hover:border-brand-400 hover:text-brand-500 dark:border-gray-700" @click="fileInput?.click()"><ImagePlus :size="18"/><span class="text-[10px] font-medium">Ekle</span></button></div></div><label class="sm:col-span-2"><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">Operasyonel Alan <span class="font-normal text-gray-400">(opsiyonel)</span></span><div class="relative"><select v-model="selectedArea" class="h-11 w-full appearance-none rounded-lg border border-gray-200 bg-white px-3 pr-9 text-sm text-gray-700 outline-none focus:border-brand-500 focus:ring-4 focus:ring-brand-500/10 dark:border-gray-700 dark:bg-gray-950 dark:text-white/90"><option value="">Operasyonel alan seçiniz</option><option v-for="item in areas" :key="item.id" :value="item.name">{{item.name}}</option></select><ChevronDown :size="15" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"/></div></label><label><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">SGK Sicil No</span><input v-model="sgk" type="text" placeholder="SGK sicil numarası" class="h-11 w-full rounded-lg border border-gray-200 px-3 text-sm text-gray-700 outline-none"/></label><label><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">NACE Kodu</span><input v-model="nace" type="text" placeholder="Örn. 27.51.01" class="h-11 w-full rounded-lg border border-gray-200 px-3 text-sm text-gray-700 outline-none"/></label><label class="sm:col-span-2"><span class="mb-1.5 block text-xs font-semibold text-gray-700 dark:text-gray-300">Tehlike Sınıfı</span><div class="relative"><select v-model="dangerClass" class="h-11 w-full appearance-none rounded-lg border border-gray-200 bg-white px-3 pr-9 text-sm text-gray-700 outline-none"><option value="">Tehlike sınıfı seçiniz</option><option>Az Tehlikeli</option><option>Tehlikeli</option><option>Çok Tehlikeli</option></select><ChevronDown :size="15" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"/></div></label></div><div class="flex justify-end gap-2 border-t border-gray-200 px-5 py-4 dark:border-gray-800"><button type="button" class="h-10 rounded-lg border border-gray-200 px-4 text-sm font-semibold text-gray-600" @click="close">Vazgeç</button><button type="button" class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-5 text-sm font-semibold text-white disabled:opacity-50" :disabled="loading||!selectedGroup||!selectedCompany||!dangerClass||(brandSelectionRequired&&!selectedBrandId)" @click="save"><LoaderCircle v-if="loading" :size="15" class="animate-spin"/><Check v-else :size="15"/> Kaydet</button></div></div></div></template>
